-- Spiral matrix LMS: seed L1/L2 mini-quiz questions (16 nodes × 5 = 80).
-- Idempotent re-run: sets passing_score=80 on seeded nodes; replaces their quiz stems + answer keys.
-- Source: draft MD (single_choice_4, passing_score:4 → nodes.passing_score=80).
-- Excludes L1-Q3-1, L1-Q4-1, L1-Q4-2 (no MD sources).
-- Apply via Supabase migration pipeline only after 上様 approval (not in this PR deploy).
-- Prerequisite migrations: 20261012_spiral_lms_mdx_mini_quiz.sql, 20261013_spiral_lms_mini_quiz_version_pass.sql,
--   20261012_spiral_lms_seed_l1_l2_nodes.sql (nodes must exist).

BEGIN;

-- Post-answer copy (private; not exposed by get_node_mini_quiz_questions until a follow-up RPC).
ALTER TABLE private.node_mini_quiz_answer_keys
  ADD COLUMN IF NOT EXISTS explanation text;

ALTER TABLE private.node_mini_quiz_answer_keys
  ADD COLUMN IF NOT EXISTS source_citation text;

UPDATE public.nodes
SET passing_score = 80,
    updated_at = now()
WHERE id IN (
  'L1-Q1-1',
  'L1-Q1-2',
  'L1-Q2-1',
  'L1-Q2-2',
  'L1-Q3-2',
  'L1-Q3-3',
  'L2-Q1-1',
  'L2-Q1-2',
  'L2-Q1-3',
  'L2-Q2-1',
  'L2-Q2-2',
  'L2-Q3-1',
  'L2-Q3-2',
  'L2-Q3-3',
  'L2-Q4-1',
  'L2-Q4-2'
);

DELETE FROM public.node_mini_quiz_questions
WHERE node_id IN (
  'L1-Q1-1',
  'L1-Q1-2',
  'L1-Q2-1',
  'L1-Q2-2',
  'L1-Q3-2',
  'L1-Q3-3',
  'L2-Q1-1',
  'L2-Q1-2',
  'L2-Q1-3',
  'L2-Q2-1',
  'L2-Q2-2',
  'L2-Q3-1',
  'L2-Q3-2',
  'L2-Q3-3',
  'L2-Q4-1',
  'L2-Q4-2'
);

